"""Regenerate the M10 renderer's initialized 0.1-degree, Q14 sine ROM."""

from math import pi, sin
from pathlib import Path


def main() -> None:
    target = Path(__file__).resolve().parents[1] / "rtl" / "sin_lut.vh"
    lines = [
        "// Generated by tools/gen_sin_lut.py; sin(0..90 degrees), Q14.",
        "// Included inside polar_to_xy's ROM initialization block.",
    ]
    for index in range(901):
        value = round(sin(index * pi / 1800) * 16384)
        lines.append(f"sin_rom[{index}] = 16'd{value};")
    target.write_text("\n".join(lines) + "\n", encoding="ascii")
    print(target)


if __name__ == "__main__":
    main()
